import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.K3sFe4KB.js";const k=JSON.parse('{"title":"Error taxonomy","description":"","frontmatter":{},"headers":[],"relativePath":"reference/errors.md","filePath":"reference/errors.md"}'),i={name:"reference/errors.md"};function o(n,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="error-taxonomy" tabindex="-1">Error taxonomy <a class="header-anchor" href="#error-taxonomy" aria-label="Permalink to &quot;Error taxonomy&quot;">​</a></h1><p>Every port and use-case error classifies into one of four kinds. The classification is a contract — MCP tools surface the <em>kind</em>, not just the message, so agents can decide retry vs ask-human.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Meaning</th><th>Retryable</th></tr></thead><tbody><tr><td><code>transient</code></td><td>Provider throttling/outage: HTTP 429, 5xx, network failures. May carry a provider <code>Retry-After</code> hint. Retries with backoff happen in the adapter; a failed apply is resume-safe.</td><td>yes</td></tr><tr><td><code>conflict</code></td><td>Drift conflict: live state diverged from recorded state for an op the plan touches. Resolve with <code>refresh</code> + re-plan, or override with <code>--force</code>.</td><td>no</td></tr><tr><td><code>auth</code></td><td>Credential acquisition/refresh failed — surface the token flow to a human (<code>cicada provider add</code>, env credentials).</td><td>no</td></tr><tr><td><code>fatal</code></td><td>Validation, capability, or logic errors — bad YAML, unsupported features, malformed state. Fix the input; never retry blindly.</td><td>no</td></tr></tbody></table><p>Only <code>transient</code> is retryable. A <code>failed</code> journal entry records the kind alongside the message so <code>--resume</code> and drift logic can reason about it.</p><h2 id="on-the-wire" tabindex="-1">On the wire <a class="header-anchor" href="#on-the-wire" aria-label="Permalink to &quot;On the wire&quot;">​</a></h2><p>MCP tools return errors as tool results with the kind attached:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;transient&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>The CLI renders the same classes in per-op apply lines and exits <code>1</code> when any op fails — check the journal for <code>errorKind</code> when scripting retries.</p>',8)])])}const u=t(i,[["render",o]]);export{k as __pageData,u as default};
